const params=new URLSearchParams(location.hash.slice(1)),id=params.get('room'),key=params.get('key'),production=params.get('production'),cue=document.querySelector('#cue'),hint=document.querySelector('#hint');let timer,sequence=0,ended=false;
function clear(){cue.hidden=true;clearTimeout(timer);}
function render(data){if(data.schema!=='btr.broadcast-cue.v1'||data.sequence<=sequence||data.expires_at<=Date.now())return;sequence=data.sequence;document.documentElement.lang=data.language;document.querySelector('#meta').textContent=`${data.clock} · ${data.source==='pitchside'?'REVIEWED AI FILM':'SYNTHETIC MATCH'} · R${data.revision}`;document.querySelector('#title').textContent=data.title;document.querySelector('#body').textContent=data.body;cue.hidden=false;hint.hidden=true;clearTimeout(timer);timer=setTimeout(clear,Math.min(6000,data.expires_at-Date.now()));}
async function connect(){
 if(!/^[a-f0-9]{24}$/.test(production||id||'')||!/^[a-f0-9]{48}$/.test(key||'')){hint.textContent='Start live output in BTR and open its renderer link.';return;}
 const config=await fetch('api-config.json').then(r=>r.json()),base=['localhost','127.0.0.1'].includes(location.hostname)?'':config.baseUrl||'';
 if(production){while(!ended){try{const r=await fetch(base+`/api/production/${production}/cue`,{headers:{Authorization:'Bearer '+key}});if(!r.ok){if(r.status===403)ended=true;throw Error('Output unavailable');}render(await r.json());}catch{clear();if(ended){hint.hidden=false;hint.textContent='Production output expired. Start a new proof run.';}}if(!ended)await new Promise(r=>setTimeout(r,1000));}return;}
 while(!ended){try{const r=await fetch(base+`/api/broadcast/${id}/stream`,{headers:{Authorization:'Bearer '+key}});if(!r.ok){if([403,410].includes(r.status)){ended=true;hint.textContent='Broadcast ended. Create a new renderer link in BTR.';hint.hidden=false;}throw Error('Disconnected');}const reader=r.body.getReader(),decoder=new TextDecoder();let buffer='';while(!ended){const {done,value}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});if(buffer.length>256000)throw Error('Stream too large');let at;while((at=buffer.indexOf('\n\n'))>=0){const block=buffer.slice(0,at);buffer=buffer.slice(at+2);const type=block.split('\n').find(l=>l.startsWith('event:'))?.slice(6).trim(),raw=block.split('\n').filter(l=>l.startsWith('data:')).map(l=>l.slice(5)).join('');if(!raw)continue;const data=JSON.parse(raw);if(type==='cue')render(data);if(type==='stopped'){clear();ended=true;}}}}catch{}if(!ended)await new Promise(r=>setTimeout(r,2000));}
}
connect().catch(()=>{hint.textContent='Output is unavailable. Reopen a live renderer link from BTR.';});
